import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"安全与权限","description":"","frontmatter":{},"headers":[],"relativePath":"guide/go/security.md","filePath":"guide/go/security.md","lastUpdated":1789529774000}'),s={name:"guide/go/security.md"};function d(i,e,n,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="安全与权限" tabindex="-1">安全与权限 <a class="header-anchor" href="#安全与权限" aria-label="Permalink to &quot;安全与权限&quot;">​</a></h1><h2 id="四层权限模型" tabindex="-1">四层权限模型 <a class="header-anchor" href="#四层权限模型" aria-label="Permalink to &quot;四层权限模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>适用场景</th><th>实现</th></tr></thead><tbody><tr><td>免登录</td><td>官网首页、市场列表</td><td>路由注册到公开分组</td></tr><tr><td>仅登录</td><td>个人中心、我的数据</td><td><code>jwt_auth</code> 中间件</td></tr><tr><td>规则鉴权</td><td>用户、角色、插件管理</td><td><code>permission</code> 中间件 + 权限标识</td></tr><tr><td>数据范围</td><td>只访问自己的数据</td><td>Service 层按 <code>user_id</code> 过滤</td></tr></tbody></table><p>前端 <code>v-permission</code> 只负责隐藏按钮，不能代替后端权限检查。插件后台接口必须在服务端再次校验权限和资源归属。</p><h2 id="rbac-五表模型" tabindex="-1">RBAC 五表模型 <a class="header-anchor" href="#rbac-五表模型" aria-label="Permalink to &quot;RBAC 五表模型&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sys_user ──┬── sys_user_role ── sys_role</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                            sys_role_menu ── sys_menu</span></span></code></pre></div><p>用户通过角色关联菜单权限，权限标识格式为 <code>模块:资源:操作</code>（如 <code>system:user:list</code>）。</p><h2 id="双令牌-jwt-机制" tabindex="-1">双令牌 JWT 机制 <a class="header-anchor" href="#双令牌-jwt-机制" aria-label="Permalink to &quot;双令牌 JWT 机制&quot;">​</a></h2><ul><li><strong>access 令牌</strong>：有效期 24 小时（<code>jwt.expire_minutes: 1440</code>），用于 API 认证。</li><li><strong>refresh 令牌</strong>：有效期 7 天（<code>jwt.refresh_expire_days: 7</code>），用于刷新 access 令牌。</li><li><strong>TokenVersion</strong>：用户改密后递增，旧令牌自动失效。</li><li><strong>黑名单</strong>：主动登出或强制下线时将令牌加入黑名单。</li><li><strong>算法白名单</strong>：仅允许 HS256。</li></ul><h2 id="登录防爆破" tabindex="-1">登录防爆破 <a class="header-anchor" href="#登录防爆破" aria-label="Permalink to &quot;登录防爆破&quot;">​</a></h2><p>连续 5 次登录失败后锁定该账号 30 分钟，由 <code>login_guard</code> 中间件实现。</p><h2 id="api-限流" tabindex="-1">API 限流 <a class="header-anchor" href="#api-限流" aria-label="Permalink to &quot;API 限流&quot;">​</a></h2><p>每 IP 每分钟 300 次请求，burst 50。超出返回 429。</p><h2 id="上传白名单" tabindex="-1">上传白名单 <a class="header-anchor" href="#上传白名单" aria-label="Permalink to &quot;上传白名单&quot;">​</a></h2><p>上传文件类型和大小受配置控制，拒绝可执行文件和脚本类型。</p><h2 id="生产密钥熔断" tabindex="-1">生产密钥熔断 <a class="header-anchor" href="#生产密钥熔断" aria-label="Permalink to &quot;生产密钥熔断&quot;">​</a></h2><p>当 <code>app.debug: false</code> 时，启动阶段检测 <code>jwt.secret</code> 是否为默认值 <code>change-me-in-production</code>，若是则拒绝启动。</p><h2 id="zip-安全检查" tabindex="-1">ZIP 安全检查 <a class="header-anchor" href="#zip-安全检查" aria-label="Permalink to &quot;ZIP 安全检查&quot;">​</a></h2><p>L2 插件 ZIP 包通过 <code>zipguard</code> 检查：</p><ul><li>zip bomb 防护：解压体积上限 200MB，单文件 50MB。</li><li>条目数上限 2000 条。</li><li>拒绝符号链接和绝对路径条目。</li></ul>`,20)])])}const b=a(s,[["render",d]]);export{u as __pageData,b as default};
